mapper.select:
select
c1.c_name as miCpyName,
pro.p_name as pName,
sec.sec_name as secName,
con.con_name as conName,
gt.Task_Text as taskText,
mn.*
from memoir_info mn
left join pre_project pro on pro.p_id=mn.p_id
left join sec_info sec on sec.sec_id=mn.sec_id
left join con_contract con on con.con_id=mn.con_id
left join Gantt_Tasks gt on gt.task_id=mn.task_id
left join Sys_Company c1 on c1.c_id=mn.mi_cpy
${authSql}

    and mn.p_id=#{params.pId}


    and mn.sec_id=#{params.secId}


    and mn.con_id=#{params.conId}


    and mn.mi_cpy=#{params.miCpy}


    and mn.state=#{params.state}


    and mn.create_uid=#{params.createUid}


    and INSTR(mn.create_uname,#{params.createUname})


    and INSTR(mn.mi_title,#{params.miTitle})


    and INSTR(pro.p_name,#{params.pName})


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and likeCname(#{params.miCpyName},c1.C_Id)=true
        
    
    
        
            and INSTR(pro.p_name,#{params.pName})
        
        
            and INSTR(c1.c_name,#{params.miCpyName})
        
    


    and INSTR(sec.sec_name,#{params.secName})


    and INSTR(con.con_name,#{params.conName})


    and mn.mi_type=#{params.miType}


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.mi_time asc
